"""
================================================================
  ESCENA DEL ENCABEZADO — grúa de muelle (QC / STS) en pixel art
  Carga un contenedor del camión al buque y descarga otro del buque al
  camión, en bucle. Es una hoja de cuadros PNG (sprite sheet) animada solo
  con CSS (background-position + steps), así que no pone lenta la página.
  Se genera con un script (qc.py); aquí solo vive el resultado.
================================================================
"""

QC_HTML = "<div class='qc-grua' aria-hidden='true'></div>"

QC_CSS = "<style>" + '.topbar{position:relative}.qc-grua{position:absolute;right:14px;bottom:0;width:236px;height:64px;background:url(data:image/png;base64,) no-repeat 0 0/236px 8192px;image-rendering:pixelated;image-rendering:crisp-edges;transform:scale(2);transform-origin:100% 100%;animation:qcGrua 16s steps(128) infinite;pointer-events:none}@keyframes qcGrua{to{background-position:0 -8192px}}@media (prefers-reduced-motion: reduce){.qc-grua{animation:none}}@media (max-width: 1250px){.qc-grua{display:none}}' + "</style>"
